+                if (skipped == false) {
+                    assert skipOffset != -1;
+                    // This is the first time this enum has skipped
+                    // since reset() was called; load the skip data:
+                    skipper.init(docTermStartFP + skipOffset, docTermStartFP, 0, 0, docFreq);
+                    skipped = true;
+                }
