+            if (docBufferUpto == BLOCK_SIZE) {
+                refillDocs();
+            }
+
+            // Now scan... this is an inlined/pared down version
+            // of nextDoc():
+            long doc;
+            while (true) {
+                doc = docBuffer[docBufferUpto];
+
+                if (doc >= target) {
+                    break;
+                }
+                ++docBufferUpto;
+            }
+
+            docBufferUpto++;
+            return this.doc = (int) doc;
+        }
+
+        @Override
+        public long cost() {
+            return docFreq;
+        }
+    }
